"""
Deterministic Contract Fixtures for Canonical Formats F1, F2, F3, F4, and F5.
Validates schedule compilation, format grammar compliance, and EditorialQC readiness.
"""
from pathlib import Path
from videopipeline.models import (
    FormatId, SourceClass, VisualSegment, create_default_format_plan,
    TimelineSchedule, EditorialVerdict, LayoutProfile
)
from videopipeline.format_validator import FormatValidator
from videopipeline.stages.stage3_compose.editorial_qc import EditorialQC


def test_contract_fixture_f1(tmp_path):
    """F1 Contract Fixture: AI Opening (Veo) + AI Images (Flow). Zero stock video."""
    plan = create_default_format_plan(FormatId.F1)
    segments = [
        VisualSegment(0, 0.0, 60.0, "veo_opening", Path("open.mp4"), description="F1 Veo Opening", source_class=SourceClass.GENERATED_VIDEO, asset_id="veo_open"),
        VisualSegment(1, 60.0, 50.0, "slideshow", Path("scene1.jpg"), description="F1 Flow Image Scene 1", source_class=SourceClass.GENERATED_IMAGE, asset_id="img_01"),
        VisualSegment(2, 110.0, 50.0, "slideshow", Path("scene2.jpg"), description="F1 Flow Image Scene 2", source_class=SourceClass.GENERATED_IMAGE, asset_id="img_02"),
        VisualSegment(3, 160.0, 40.0, "slideshow", Path("scene3.jpg"), description="F1 Flow Image Scene 3", source_class=SourceClass.GENERATED_IMAGE, asset_id="img_03")
    ]
    sched = TimelineSchedule(story_dir=tmp_path, audio_path=Path("audio.m4a"), total_duration=200.0, segments=segments)

    # 1. Format grammar validation
    val_res = FormatValidator.validate_timeline(sched.segments, plan)
    assert val_res["valid"] is True
    assert val_res["format"] == "F1"

    # 2. Editorial QC evaluation
    qc_res = EditorialQC.evaluate_timeline(sched.segments, sched.total_duration, plan)
    assert qc_res.verdict == EditorialVerdict.EDIT_READY
    assert len(qc_res.reasons) == 0


